create table customer (is_active boolean not null, created_at timestamp(6) with time zone, id bigint generated by default as identity, version bigint not null, external_ref uuid, email_address varchar(255), first_name varchar(255), status_as_text varchar(255) check ((status_as_text in ('NEW','ACTIVE','CLOSED'))), primary key (id));
create table order_line (quantity_ordered integer not null, unit_price numeric(38,2), id bigint generated by default as identity, version bigint not null, primary key (id));
